list_categories.code:
final response = await client.categories.listCategories(
  queryParams: {'limit': 10, 'offset': 10, 'sort': 'name', 'dir': 'asc'},
);
final categories = (response.map as Map)['categories'] as List;
for (final category in categories) {
  final general = (category as Map)['general'] as Map;
  print('${category['id']} ${general['name']} ${general['url']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print('${pagination['total']} ${pagination['has_next']}');

count_categories.code:
final response = await client.categories
    .countCategories(queryParams: {'searchText': 'seasonal'});
final categories = (response.map as Map)['categories'] as Map;
print(categories['count']);

check_category_name.code:
final response =
    await client.categories.checkCategoryName('Seasonal Produce');
print((response.map as Map)['available']);

create_category.code:
final response = await client.categories.createCategory({
  'category': {
    'general': {
      'name': 'Seasonal Produce',
      'title': 'Seasonal Produce',
      'heading': 'Fresh this season',
      'summary': 'Fruit and vegetables picked this week',
      'parent_category': {'id': 4310},
    },
    'description': {'content': '<p>What is in season right now.</p>'},
    'availability_visibility': {
      'visible': true,
      'custom_sorting': true,
      'default_sorting': 'alpha_asc',
    },
    'tax_shipping': {'tax_message': 'Prices include GST'},
    'assign_products': {
      'products': [101, 102],
    },
  },
});
final category = (response.map as Map)['category'] as Map;
final general = category['general'] as Map;
print('${category['id']} ${general['sku']} ${general['url']}');

get_category.code:
final response = await client.categories.getCategory(4321);
