update_category.code:
final response = await client.categories.updateCategory(4321, {
  'category': {
    'general': {'name': 'Seasonal Produce', 'heading': 'New heading'},
  },
});
final category = (response.map as Map)['category'] as Map;
final general = category['general'] as Map;
print('${general['name']} ${general['heading']} ${general['summary']}');

patch_category.code:
final response = await client.categories.patchCategory(4321, {
  'category': {
    'general': {'summary': 'Updated summary'},
    'availability_visibility': {'visible': false},
  },
});
final category = (response.map as Map)['category'] as Map;
final general = category['general'] as Map;
final visibility = category['availability_visibility'] as Map;
print('${general['summary']} ${visibility['visible']}');

get_category_section.code:
final response =
    await client.categories.getCategorySection(4321, 'tax_shipping');
