patch_category_section.code:
final response =
    await client.categories.patchCategorySection(4321, 'assign_products', {
  'category': {
    'assign_products': {
      'products': [101, 102, 103],
    },
  },
});
final category = (response.map as Map)['category'] as Map;
final products = (category['assign_products'] as Map)['products'] as List;
for (final product in products) {
  print('${(product as Map)['id']} ${product['sku']} ${product['name']}');
}
